current.custom_css:
.sf-nav li.sf-menu-item--mega .sf-menu-submenu__content {
  padding-top: 20px;
}

.sf-nav li.sf-menu-item--mega .sf__menu-item-level2 .sf__sub-menu-link2 {
  display: none;
}
.sf-nav li.sf-menu-item--mega .sf__menu-item-level2 .sf__sub-menu-column {
  margin-top: 0;
}


.sf-slider__controls button {
  background: #FFFFFF;
  box-shadow: 0px 10px 10px rgba(0, 0, 0, 0.11);
  border-radius: 50%;
  border: 0;
}

.sf-slider__controls button:hover {
  box-shadow: 0px 10px 10px rgba(0, 0, 0, 0.11);
}

.sf__featured-collection .sf-slider__controls--absolute button {
  left: -35px;
}

.sf__featured-collection .sf-slider__controls--absolute button.sf-slider__controls-next {
  right: -35px;
}

.sf__btn.sf__btn-secondary, 
a.sf__btn.sf__btn-secondary, 
button.sf__btn.sf__btn-secondary {
  background: #D0D0D0;
  border-color: #D0D0D0;
}

.sf__btn.sf__btn-link, 
a.sf__btn.sf__btn-link, 
button.sf__btn.sf__btn-link {
  line-height: 1;
  padding: 2px 0;
}

.sf__btn.sf__btn-link:after, .sf__btn.sf__btn-link:before, a.sf__btn.sf__btn-link:after, 
a.sf__btn.sf__btn-link:before, button.sf__btn.sf__btn-link:after, button.sf__btn.sf__btn-link:before {
  height: 1px;
}

.pcard-variant-option .sf__tooltip-item,
.widget-filter--color .sf__tooltip-item {
  background: transparent;
}

.sf__pcard-name {
  font-family: 'SF-Body-font';
  letter-spacing: 0;
  line-height: 135%;
}

.sf__pcard.sf__pcard-style-1 {
  background: #fff;
  transition: all .3s ease;
  border: 1px solid #E9E9E9;
  height: 100%;
}

.sf__pcard.sf__pcard-style-1 .sf__pcard-image {
  padding: 20px 20px 0;
}

.sf__pcard.sf__pcard-style-1 .sf__pcard-content {
  padding: 0 20px 20px;
}

.sf__pcard.sf__pcard-style-1:hover {
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.12);
}

.sf-nav .sf-menu-item-parent .sf__parent-item {
  font-size: 15px;
  font-weight: 600;
}

.logo-left__2l .sf-menu-wrapper__desktop {
  justify-content: center;
}

.sf-hero__title {
  line-height: 125%;
  letter-spacing: 1px;
  margin-bottom: 10px;
}

.sf-hero__text {
  color: #000;
  line-height: 144%;
  margin-bottom: 30px;
}

.sf__custom-content-1 .image-card {
  height: 100%;
}

.custom__img-card .image-card__content .image__card-heading-group {
  display: flex;
  flex-direction: column-reverse;
}

.custom__img-card .image-card__content .image__card-heading {
  line-height: 116%;
  margin-bottom: 10px;
  letter-spacing: 1px;
}

.custom__img-card .image-card__content .image__card-subheading {
  margin-bottom: 22px;
  line-height: 163%;
}

.collection-list .collection-card__info {
  margin-top: 10px;
}

.collection-list .collection-card__info h3 a {
  font-family: 'SF-Body-font';
  font-weight: 600;
  letter-spacing: 0;
  font-size: 15px;
}

.custom__img-card-1 .image-card__content {
  padding: 26px 20px;
}

.custom__img-card-1 .image-card__content .image-card__content-inner {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
}

.custom__img-card-1 .image-card__content .image__card-heading {
  font-size: 26px;
  letter-spacing: 1px;
  line-height: 130%;
}

.sf-icon-box .sf-icon-box__text {
  margin-top: 34px;
}

.sf-icon-box .sf-icon-box__text h3 {
  font-family: 'SF-Body-font';
  font-size: 19px;
  letter-spacing: 0;
  font-weight: 600;
  margin-bottom: 13px;
}

.sf-instagram .section-my {
  margin-bottom: 0;
}

.sf__footer-block-title {
  font-size: 15px;
  font-family: 'SF-Body-font';
  letter-spacing: 0;
  font-weight: 600;
  text-transform: uppercase;
}

.sf__newsletter-block-desc {
  padding: 0;
}

.sf-footer form.sf__footer-form-newsletter .sf__newletter__form-input {
  border-radius: 0;
  box-shadow: 0px 0px 20px rgb(0 0 0 / 12%);
}

.sf__footer-form-newsletter .sf__form-submit {
  background: #000;
  color: #fff;
}

.widget-filter__list .sf__list-row .widget-filter__list-link {
  display: inline-block !important;
}

@media screen and (min-width: 1280px) {
  .logo-left__2l .sf-search-form--full {
    min-width: 700px;
    background: #fff;
    border-radius: 0;
    box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.12);
    border: 1px solid #E9E9E9;
    margin-right: 130px;
    position: relative;
  }

  .logo-left__2l .sf-search-form--full button {
    background: #000;
    color: #fff;
    padding-top: 7px;
    padding-bottom: 7px;
  }

  .sf-hero__text {
    font-size: 18px;
  }

  .custom__img-card .image-card__content .image__card-heading {
    font-size: 50px;
  }

  .sf__footer-block-newsletter .sf__footer-block-title {
    font-family: 'SF-Heading-font';
    letter-spacing: 1px;
    font-weight: 400;
    font-size: 36px;
    line-height: 150%;
    margin-bottom: 15px;
  }

  .sf__footer-form-newsletter {
    margin-top: 28px;
    max-width: 300px;
  }
}

@media screen and (min-width: 1536px) {
  .sf-hero__title {
    font-size: 60px;
  }
}

@media screen and (min-width: 1920px) {
  .sf-hero__title {
    font-size: 80px;
  }
}
